/**
 * Synthesize PagerDuty v3 webhook bodies for `agent-sdk pagerduty replay`, so a
 * local `pagerdutyChannel()` can be exercised without a PagerDuty account
 * or tunnel. The bodies follow PagerDuty's documented v3 shapes: lifecycle
 * events carry the incident as `data`, notes carry it as `data.incident`.
 */
import { randomUUID } from "node:crypto";
/** Event types `replay` can synthesize, in the order an incident usually sees them. */
export const PAGERDUTY_REPLAYABLE_EVENTS = [
    "incident.triggered",
    "incident.acknowledged",
    "incident.annotated",
    "incident.escalated",
    "incident.resolved",
    "incident.reopened",
];
function isPagerDutyReplayableEvent(value) {
    return PAGERDUTY_REPLAYABLE_EVENTS.some((event) => event === value);
}
const STATUS_BY_EVENT = {
    "incident.triggered": "triggered",
    "incident.acknowledged": "acknowledged",
    "incident.annotated": "triggered",
    "incident.escalated": "triggered",
    "incident.resolved": "resolved",
    "incident.reopened": "triggered",
};
export const PAGERDUTY_REPLAY_DEFAULT_INCIDENT_ID = "PREPLAY1";
const SUBDOMAIN = "example";
const SERVICE = {
    id: "PSVCREP",
    type: "service_reference",
    summary: "replayed-service",
    html_url: `https://${SUBDOMAIN}.pagerduty.com/service-directory/PSVCREP`,
};
const RESPONDER = {
    id: "PUSERREP",
    type: "user_reference",
    summary: "Replay Responder",
    html_url: `https://${SUBDOMAIN}.pagerduty.com/users/PUSERREP`,
};
/**
 * Pick the events to replay. Accepts full names (`incident.resolved`) or
 * the action alone (`resolved`); `*` selects every declared event that can
 * be synthesized. Defaults to `incident.triggered`.
 */
export function selectPagerDutyReplayEvents(input) {
    const { requested, declared } = input;
    const replayable = new Set(PAGERDUTY_REPLAYABLE_EVENTS);
    if (requested === undefined) {
        return { events: ["incident.triggered"], unsupported: [] };
    }
    if (requested.length === 1 && requested[0] === "*") {
        const pool = declared.length === 0 ? PAGERDUTY_REPLAYABLE_EVENTS : declared;
        return {
            events: PAGERDUTY_REPLAYABLE_EVENTS.filter((event) => pool.includes(event)),
            unsupported: [],
        };
    }
    const events = [];
    const unsupported = [];
    for (const raw of requested) {
        const name = raw.startsWith("incident.") ? raw : `incident.${raw}`;
        if (isPagerDutyReplayableEvent(name) && replayable.has(name)) {
            events.push(name);
        }
        else {
            unsupported.push(raw);
        }
    }
    return { events, unsupported };
}
/**
 * One v3 delivery body for `eventType` on `incidentId`. A trigger comes
 * from PagerDuty itself (no `agent`); every other event is a person's
 * action, so it dispatches rather than being skipped as the agent's echo.
 */
export function synthesizePagerDutyEvent(input) {
    const incidentId = input.incidentId ?? PAGERDUTY_REPLAY_DEFAULT_INCIDENT_ID;
    const incidentUrl = `https://${SUBDOMAIN}.pagerduty.com/incidents/${incidentId}`;
    const data = input.eventType === "incident.annotated"
        ? {
            id: `PNOTE${randomUUID().slice(0, 6).toUpperCase()}`,
            type: "incident_note",
            content: input.note ?? "Replayed note from agent-sdk pagerduty replay.",
            trimmed: false,
            incident: {
                id: incidentId,
                type: "incident_reference",
                html_url: incidentUrl,
            },
        }
        : {
            id: incidentId,
            type: "incident",
            number: 1,
            title: "Replayed incident from agent-sdk pagerduty replay",
            status: STATUS_BY_EVENT[input.eventType],
            urgency: "high",
            incident_key: `replay-${incidentId}`,
            html_url: incidentUrl,
            created_at: new Date().toISOString(),
            service: SERVICE,
            assignees: [RESPONDER],
            teams: [],
        };
    return {
        event: {
            id: randomUUID(),
            event_type: input.eventType,
            resource_type: "incident",
            occurred_at: new Date().toISOString(),
            agent: input.eventType === "incident.triggered" ? null : RESPONDER,
            client: { name: "agent-sdk pagerduty replay" },
            data,
        },
    };
}
